#!/usr/bin/env python3
# Writes decisions.json: the judgement of every difference the audit run found, the lint triage, and what was not
# checked. Kept as a script because the same decision recurs across examples; edit here and run it, then run
# node tools/build-example-audit.mjs. Each difference names what it covers in results.json (pairs, layout numbers
# called "metrics", replayed steps as "replay name#step", checks); the builder refuses a result nothing covers.
import json, os
HOST = 'Chromium on macOS in this run. The control is the browser\'s own; on a Windows host the same keys follow Windows more closely, which this audit did not measure.'
def d(id, kind, summary, real, example, severity, status, covers, note=None):
    out = {'id': id, 'kind': kind, 'summary': summary, 'real': real, 'exampleDoes': example, 'severity': severity, 'status': status, 'covers': covers}
    if note: out['note'] = note
    return out
def spacing(id, covers, what):
    return d(id, 'layout', f'{what} follow the example page\'s own spacing, not dialog units.', 'Rows 12 dialog units apart (19 or 20 px); the first row 11 units below the top of a group box.', 'The page layer\'s 8 px gaps: rows 23 px apart.', 'low', 'open', covers, 'The stage of a non-dialog example is laid out by examples/widgets/shared.mjs, in both densities. Using the kit\'s dialog layout attributes there would change every example page.')
E = {}
def ex(id, families, counterpart, differences=(), lint=None, notChecked=(), verdict=None, verdictNote=None):
    E[id] = {'families': families, 'counterpart': counterpart, 'differences': list(differences), 'notChecked': [{'what': w, 'why': y} for w, y in notChecked]}
    if lint: E[id]['lint'] = lint
    if verdict: E[id]['verdict'] = verdict
    if verdictNote: E[id]['verdictNote'] = verdictNote
NC_STATES = ('pressed, focused and hover states as pixels', 'the real captures are of controls at rest; pressed and focused states were compared for the kit\'s atlas earlier (tools/win95-reference/README.md), not for this page')
NC_TEXT = ('text pixels and anything whose width follows its text', 'the real system draws MS Sans Serif, a bitmap font; the browser draws the host\'s font')
NC_ACCESS = ('access keys (Alt with an underlined letter)', 'the examples define none; the real behaviour is recorded in dialog-access-keys')

